impl SpinLock {
    pub fn new() -> Self {
        Self { locked: AtomicBool::new(false) }
    }
    pub fn lock(&self) {
        self.locked.try_lock().unwrap();
    }
    pub fn unlock(&self) {
        self.locked.try_unlock().unwrap();
    }
}
```

